entries[99659] = { ["name"] = "Mantelung des Chronomanten", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\n+1 Intelligenz\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 2.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Intelligenz\n\nHaltbarkeit 100 / 100\nKlassen: Magier\nOrnat des Chronomanten (0/5)\nRoben des Chronomanten\nMantelung des Chronomanten\nHandschuhe des Chronomanten\nKapuze des Chronomanten\nGamaschen des Chronomanten\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Euer Zauber 'Arkane Geschosse' verringert die Manakosten Eures nächsten Wirkens von 'Arkanschlag' innerhalb von 10 Sek. um 25%. Bis zu 4-mal stapelbar. Das Aufzehren von 'Hirnfrost' erhöht den Schaden Eures nächsten Wirkens von 'Eislanze', 'Frostblitz', 'Frostfeuerblitz' oder 'Kältekegel' um 20%. Das Aufzehren von 'Pyroschlag!' erhöht Euer Tempo 5 Sek. lang um 12 . Bis zu 5-mal stapelbar.\n(4) Set : Euer Zauber 'Arkane Geschosse' hat eine Chance von 15%, 'Arkane Geschosse!' nicht aufzuzehren. Das Aufzehren von 'Hirnfrost' hat eine Chance von 30%, einen eisigen Felsen auf Euer Ziel stürzen zu lassen. 'Infernoschlag' lässt Euer nächstes Wirken von 'Pyroschlag' kritisch treffen.\nVerkaufspreis:" }
entries[99660] = { ["name"] = "Kopfschutz der unablässigen Wacht", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n8 Rüstung\n+1 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 1.\n\nMetasockel\nPrismatischer Sockel\nSockelbonus: + 7 Beweglichkeit\n\nHaltbarkeit 100 / 100\nKlassen: Jäger\nSchlachtrüstung der unablässigen Wacht (0/5)\nKopfschutz der unablässigen Wacht\nBeinschützer der unablässigen Wacht\nSchiftung der unablässigen Wacht\nTunika der unablässigen Wacht\nHandschuhe der unablässigen Wacht\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Erhöht den von 'Arkaner Schuss', 'Gezielter Schuss' und 'Mehrfachschuss' verursachten Schaden um 15%.\n(4) Set : Der Einsatz von 'Explosivschuss' hat eine Chance von 40%, keine Aufladung von 'Sichern und Laden' aufzuzehren. Die kritische Trefferchance von 'Gezielter Schuss' ist um 10% erhöht. Offensivfähigkeiten, die während der Dauer von 'Zorn des Wildtiers' eingesetzt werden, erhöhen allen von Euch verursachten Schaden um 4% und allen von Eurem Begleiter verursachten Schaden um 2%. Bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[99661] = { ["name"] = "Beinplatten des beflügelten Triumphes", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n15 Rüstung\n+2 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Stärke\n\nHaltbarkeit 120 / 120\nKlassen: Paladin\nSchlachtrüstung des beflügelten Triumphes (0/5)\nSchulterstücke des beflügelten Triumphes\nKampfplatte des beflügelten Triumphes\nStulpen des beflügelten Triumphes\nHelm des beflügelten Triumphes\nBeinplatten des beflügelten Triumphes\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Wenn Ihr 'Exorzismus' einsetzt, wird sämtlicher Schaden 6 Sek. lang um 5% erhöht.\n(4) Set : Zauber, die Heilige Kraft verbrauchen, haben eine Chance von 25%, dass Euer nächstes Wirken von 'Göttlicher Sturm' kostenlos ist und 30% mehr Schaden verursacht.\nVerkaufspreis:" }
entries[99662] = { ["name"] = "Schulterstücke des beflügelten Triumphes", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n11 Rüstung\n+1 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Stärke\n\nHaltbarkeit 100 / 100\nKlassen: Paladin\nSchlachtrüstung des beflügelten Triumphes (0/5)\nSchulterstücke des beflügelten Triumphes\nKampfplatte des beflügelten Triumphes\nStulpen des beflügelten Triumphes\nHelm des beflügelten Triumphes\nBeinplatten des beflügelten Triumphes\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Wenn Ihr 'Exorzismus' einsetzt, wird sämtlicher Schaden 6 Sek. lang um 5% erhöht.\n(4) Set : Zauber, die Heilige Kraft verbrauchen, haben eine Chance von 25%, dass Euer nächstes Wirken von 'Göttlicher Sturm' kostenlos ist und 30% mehr Schaden verursacht.\nVerkaufspreis:" }
entries[99663] = { ["name"] = "Schiftung der himmlischen Harmonie", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n8 Rüstung\n+1 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 2.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Beweglichkeit\n\nHaltbarkeit 100 / 100\nKlassen: Schamane\nSchlachtrüstung der himmlischen Harmonie (0/5)\nKürass der himmlischen Harmonie\nHandschutz der himmlischen Harmonie\nHelm der himmlischen Harmonie\nBeinschützer der himmlischen Harmonie\nSchiftung der himmlischen Harmonie\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Das Wirken Eures Zaubers 'Elemente entfesseln' gewährt Euren Angriffen 10 Sek. lang eine Chance, eine zufällige Waffenverstärkung zu entfesseln.\n(4) Set : Wenn 'Flammenschock' regelmäßigen Schaden verursacht, besteht eine Chance von 5%, dass die Abklingzeit von 'Lavapeitsche' abgeschlossen wird. (Procchance: 5%, 100ms Abklingzeit)\nVerkaufspreis:" }
entries[99664] = { ["name"] = "Schulterschutz des gezeichneten Tals", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n5 Rüstung\n+1 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 1.\n\nPrismatischer Sockel\nPrismatischer Sockel\nSockelbonus: + 4 Beweglichkeit\n\nHaltbarkeit 100 / 100\nKlassen: Druide\nRüstung des gezeichneten Tals (0/5)\nHandschützer des gezeichneten Tals\nKopfschutz des gezeichneten Tals\nBundhose des gezeichneten Tals\nSchulterschutz des gezeichneten Tals\nTunika des gezeichneten Tals\nAltes Set: Bonus ist nicht aktiv\n(2) Set : Wenn 'Baumrinde' schwindet, werden automatisch 'Wilde Verteidigung' aktiviert und 'Rasende Regeneration' in Höhe von 20 Wut eingesetzt.\n(4) Set : Beim Aktivieren von 'Rasende Regeneration' oder 'Wilde Verteidigung' werdet Ihr 8 Sek. lang mit einem regelmäßigen Heileffekt basierend auf 30% Eurer Angriffskraft belegt.\nVerkaufspreis:" }
